-- Guardian portal accounts. Enrolling a learner runs
-- accounts/guardian_provisioning.py: every guardian row with an email is
-- linked to an account with that email, created if missing with an
-- UNUSABLE password (nobody can sign in until an admin sets one). A row
-- whose email belongs to a staff account is skipped (Bea's father).
-- Rows without an email are linked by exact name inside the household.
ON CONFLICT (email) DO NOTHING;

SELECT setval('users_user_id_seq', GREATEST((SELECT MAX(user_id) FROM users), 1));

UPDATE guardians g SET user_id = u.user_id
  FROM users u
 WHERE lower(u.email) = lower(g.email_address) AND u.role = 'guardian'
   AND g.student_id IN (100, 103, 104, 105, 110, 111, 112, 113, 114, 115, 116, 117, 120, 125, 126, 127, 128, 129, 131, 138, 140, 141, 143, 147, 148, 151, 152, 153, 154, 155, 156);

UPDATE guardians g SET user_id = src.user_id
  FROM guardians src
  JOIN students ss ON ss.student_id = src.student_id,
       students s
 WHERE s.student_id = g.student_id
   AND s.household_id IS NOT NULL AND ss.household_id = s.household_id
   AND src.student_id <> g.student_id AND src.user_id IS NOT NULL
   AND g.user_id IS NULL AND g.email_address IS NULL
   AND lower(regexp_replace(src.full_name, '\s+', ' ', 'g')) = lower(regexp_replace(g.full_name, '\s+', ' ', 'g'))
   AND g.student_id IN (100, 103, 104, 105, 110, 111, 112, 113, 114, 115, 116, 117, 120, 125, 126, 127, 128, 129, 131, 138, 140, 141, 143, 147, 148, 151, 152, 153, 154, 155, 156);


