BEGIN
  IF (SELECT count(*) FROM grades WHERE enrollment_id IN (SELECT enrollment_id FROM enrollments e JOIN students s USING (student_id) WHERE s.lrn LIKE '136700000%')) <> 689 THEN
    RAISE EXCEPTION 'grades did not all resolve to a subject';
  END IF;
END $$;



-- =====================================================
-- 13. ATTENDANCE
-- Every school day of each enrollment's span -- weekdays, minus the year's
-- holidays, days off and quarter breaks -- except the listed absences,
-- excused days and late arrivals. 2026-2027 runs up to today. Recorded by
-- the section's first adviser, except: Rica's rows switch recorder at her
-- move to Pearl; Grade 9 Sapphire (no adviser) is taken by the registrar;
-- Grade 4 Luna is Arnel Pascual's until 2026-09-17, nobody's on 09-18 (he
-- had resigned), Carla Bernardo's from 09-21. Today: Grade 10 Ruby hasn't
-- taken attendance and Patrick hasn't been marked in Grade 6 Aguinaldo.
-- =====================================================

CREATE TEMP TABLE seed_att_ranges (eid bigint, d_from date, d_to date, recorder text) ON COMMIT DROP;

CREATE TEMP TABLE seed_att_skip (eid bigint, day date) ON COMMIT DROP;


CREATE TEMP TABLE seed_att_exceptions (eid bigint, day date, status text, remarks text) ON COMMIT DROP;

SELECT r.eid, g.day, COALESCE(x.status, 'P'), x.remarks, u.user_id,
       g.day + time '07:40', g.day + time '07:40'
  FROM seed_att_ranges r
  JOIN enrollments e ON e.enrollment_id = r.eid
  CROSS JOIN LATERAL (SELECT gs::date AS day FROM generate_series(r.d_from, r.d_to, interval '1 day') gs) g
  LEFT JOIN seed_att_exceptions x ON x.eid = r.eid AND x.day = g.day
  LEFT JOIN users u ON u.email = r.recorder
 WHERE extract(isodow FROM g.day) < 6
   AND NOT EXISTS (SELECT 1 FROM seed_att_skip k WHERE k.eid = r.eid AND k.day = g.day)
   AND NOT EXISTS (
         SELECT 1 FROM academic_calendar_events ev
          WHERE ev.school_year = e.school_year
            AND ev.event_type IN ('holiday', 'school_day_off', 'quarter_break')
            AND g.day BETWEEN ev.start_date AND ev.end_date);

DO $$
BEGIN
  IF (SELECT count(*) FROM seed_att_exceptions x
       WHERE NOT EXISTS (SELECT 1 FROM attendance_records a
                          WHERE a.enrollment_id = x.eid AND a.date = x.day AND a.status = x.status)) > 0 THEN
    RAISE EXCEPTION 'an absence/late day fell outside the school days';
  END IF;
  IF (SELECT count(*) FROM attendance_records WHERE enrollment_id IN (SELECT DISTINCT eid FROM seed_att_ranges)) <> 5835 THEN
    RAISE EXCEPTION 'attendance count differs from the generator''s calendar (expected 5835)';
  END IF;
  IF EXISTS (SELECT 1 FROM attendance_records a JOIN seed_att_ranges r ON r.eid = a.enrollment_id
              WHERE a.recorded_by IS NULL) THEN
    RAISE EXCEPTION 'an attendance recorder email did not resolve';
  END IF;
END $$;


-- =====================================================
-- 14. INVOICES, INSTALLMENTS AND PAYMENTS
-- Computed with billing-service's own rules: the discount waterfall on tuition
-- (voucher, scholarships, payment plan, Early Bird), installments counted from
-- the year's start month and due on the last day of the month, remainder on the
-- last one; prorated for a transfer-in; closed out on a transfer-out; a void
-- only flips the invoice (its installments are left as they were); a re-issue
-- voids the original and moves its payments across. Senior High is billed once
-- a year, on the 1st-semester row. Installments still owed past their due date
-- are overdue, as flag_overdue_installments marks them (never on void ones).
-- =====================================================

